    fn render_inner(
        &self,
        config: Option<(&Config, &Path)>,
        input: &str,
        base: &Path,
        target: &Path,
    ) -> Result<String> {
        let resolution = self.resolution.clone();
        let used = Arc::new(Mutex::new(BTreeSet::new()));
