    config: &Config,
    hooks: &[hooks::BootstrapHook],
    phase: BootstrapHookPhase,
    dry_run: bool,
) -> Result<()> {
    if !bootstrap_hooks_enabled() {
        debug!("bootstrap: {phase} hooks disabled");
        return Ok(());
    }
    hooks::run_phase(config, hooks, phase, dry_run).await
}

