    }
}

fn escape_html(s: &str) -> String {
    let mut output = String::with_capacity(s.len() * 2);
    for c in s.chars() {
        match c {
            '&' => output.push_str("&amp;"),
            '<' => output.push_str("&lt;"),
            '>' => output.push_str("&gt;"),
            '"' => output.push_str("&quot;"),
            '\'' => output.push_str("&#x27;"),
            _ => output.push(c),
        }
    }
    output
}

fn tera_v1_truthy(value: &Value) -> bool {
    if value.is_none() {
        false
    } else if let Some(b) = value.as_bool() {
        b
    } else if let Some(s) = value.as_str() {
        !s.is_empty()
    } else if let Some(arr) = value.as_array() {
        !arr.is_empty()
    } else if let Some(map) = value.as_map() {
        !map.is_empty()
    } else if let Some(n) = value.as_number() {
        n.as_integer().is_some_and(|n| n != 0) || value.as_f64().is_some_and(|n| n != 0.0)
    } else {
        true
    }
}

fn tera_v1_int(value: Value, args: Kwargs) -> TeraResult<Value> {
    let default = args.get::<i64>("default")?;
    let base = args.get::<u32>("base")?.unwrap_or(10);
    if !(2..=36).contains(&base) {
        return Err(tera_err(format!(
            "int filter `base` must be between 2 and 36, got {base}"
        )));
    }

    let fallback = || {
        warn_tera_v1_filter(
            "tera-v1-int-default",
            "int(default=...)",
            "Invalid integer conversions should be handled explicitly.",
    }];
    let idiomatic_filenames = BTreeMap::new();
    for root in roots {
        let paths = config_paths_in_dir_with_filenames(&root, &DEFAULT_CONFIG_FILENAMES);
        let config_files = load_config_files_from_paths(&paths, &idiomatic_filenames).await?;
        let vars_config = config.with_config_files(config_files.clone());
        let vars_results = load_vars(&vars_config).await?;
        let mut vars = config.vars.clone();
        vars.extend(
            vars_results
                .vars
                .iter()
                .map(|(key, (value, _))| (key.clone(), value.clone())),
        );
        let mut tera_ctx = config.tera_ctx.clone();
        tera_ctx.insert("vars", &vars);
        tera_ctx.insert("config_root", &root);
        maps.push(BootstrapConfigMap {
            config_files,
            tera_ctx,
            config_root: Some(root),
            vars_results,
        });
    }
    Ok(maps)
}

