fn insert_tera1_context_value(
    data: &mut JsonMap<String, JsonValue>,
    context: &Context,
    key: &str,
) -> TeraResult<()> {
    if data.contains_key(key) {
        return Ok(());
    }
    if let Some(value) = context.get(key) {
        data.insert(
            key.to_string(),
            serde_json::to_value(value).map_err(|e| tera_err(e.to_string()))?,
